let glossaryQuery='',glossaryCategory='',glossaryRisk=false;
function termWarnings(t){return glossaryWarnings.filter(w=>t.zh.split('／').some(z=>z===w.term)||w.term==='模具'&&t.id===1||w.term==='放電'&&t.id===44||w.term==='模仁'&&t.id===5)}
function normalizeTerm(v){return v.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('ß','ss')}
function filteredTerms(){const q=normalizeTerm(glossaryQuery.trim());return glossaryTerms.filter(t=>(!glossaryCategory||t.category===glossaryCategory)&&(!glossaryRisk||termWarnings(t).length)&&(!q||normalizeTerm([t.zh,t.en,t.de,t.context].join(' ')).includes(q)))}
function glossaryResults(){const rows=filteredTerms();return `<div class="cardhead"><h2>術語對照</h2><span role="status">顯示 ${rows.length} / ${glossaryTerms.length} 詞</span></div>${rows.length?`<div class="tablewrap"><table class="glossary-table"><thead><tr><th>中文／台灣常用詞</th><th>English</th><th>Deutsch</th><th>使用情境</th><th>詳情</th></tr></thead><tbody>${rows.map(t=>`<tr><td><b>${esc(t.zh)}</b><small>${esc(t.category)}</small>${termWarnings(t).length?'<span class="badge amber">注意語境</span>':''}</td><td lang="en">${esc(t.en)}</td><td lang="de">${esc(t.de)}</td><td>${esc(t.context)}</td><td><button onclick="openTerm(${t.id})" aria-label="查看 ${esc(t.zh)} 詳情">查看</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">沒有符合的術語，請調整關鍵字或清除篩選。</div>'}`}
function updateGlossary(){document.querySelector('#glossaryResults').innerHTML=glossaryResults()}
function resetGlossary(){glossaryQuery='';glossaryCategory='';glossaryRisk=false;render()}
function glossaryPage(){const cats=[...new Set(glossaryTerms.map(t=>t.category))];return title('專業翻譯知識庫','查找模具專業用語，核對中英德譯法與使用情境。','<span class="badge amber">TBD · 規劃預覽</span>')+`<div class="note">已收錄附件 67 個術語，可搜尋與查閱。AI 翻譯串接、客戶專屬詞彙及審核版本管理尚待規劃，詞條尚未經企業審核。</div><section class="card"><div class="glossary-toolbar"><label>搜尋術語<input type="search" placeholder="搜尋中文、English、Deutsch 或使用情境" value="${esc(glossaryQuery)}" oninput="glossaryQuery=this.value;updateGlossary()"></label><label>專業分類<select onchange="glossaryCategory=this.value;updateGlossary()"><option value="">全部分類（67）</option>${cats.map(c=>`<option value="${esc(c)}" ${c===glossaryCategory?'selected':''}>${esc(c)}（${glossaryTerms.filter(t=>t.category===c).length}）</option>`).join('')}</select></label><label class="glossary-risk"><input type="checkbox" ${glossaryRisk?'checked':''} onchange="glossaryRisk=this.checked;updateGlossary()">僅顯示誤譯提醒</label><button onclick="resetGlossary()">清除篩選</button></div><div id="glossaryResults">${glossaryResults()}</div></section><details class="card glossary-sources"><summary>資料來源與後續規劃</summary><p>資料取自附件《模具廠常用專業術語｜中文・英文・德文對照》。下列為附件列出的參考來源，本頁未逐條重新驗證。</p><ul><li><a href="https://media.hasco.com/marketing/Content/Mediathek/Poster/Form/Form_POST_DE.pdf" target="_blank" rel="noopener noreferrer">HASCO：模具標準件與結構術語</a></li><li><a href="https://www.protolabs.com/en-gb/resources/guides-and-trend-reports/injection-moulding-guide-process-design-tips-materials/" target="_blank" rel="noopener noreferrer">Protolabs：射出成型指南</a> · <a href="https://www.protolabs.com/de-de/ressourcen/blog/fehler-beim-spritzgiessen-und-ihre-vermeidung/" target="_blank" rel="noopener noreferrer">德文射出缺陷資料</a></li><li><a href="https://www.engelglobal.com/de/de/digitale-loesungen/abmusterung-von-spritzgiesswerkzeugen" target="_blank" rel="noopener noreferrer">ENGEL：試模與製程術語</a></li><li><a href="https://www.meusburger.com/de-de/formenbau/anwendungsbereiche/werkzeugbau/erodieren" target="_blank" rel="noopener noreferrer">Meusburger：模具加工術語</a></li></ul><p>後續欄位：中文標準詞、現場別稱、詞類、流程階段、允許同義詞、禁止誤譯、圖面例句；另待確認客戶適用範圍、審核者及版本。</p></details>`}
function openTerm(id){const t=glossaryTerms.find(t=>t.id===id);if(!t)return;const warnings=termWarnings(t);caseDialog('termDialog',`<h2 id="termDialogTitle">${esc(t.zh)}</h2><p>${esc(t.category)} · 詞條 ${t.id} / 67</p><dl class="term-details"><dt>中文／台灣常用詞</dt><dd lang="zh-Hant">${termCopyItems(t,'zh')}</dd><dt>English</dt><dd lang="en">${termCopyItems(t,'en')}</dd><dt>Deutsch</dt><dd lang="de">${termCopyItems(t,'de')}</dd><dt>實際意思／使用情境</dt><dd>${esc(t.context)}</dd></dl>${warnings.map(w=>`<div class="note"><strong>容易誤譯：${esc(w.wrong)}</strong><p>${esc(w.advice)}</p></div>`).join('')}<p id="termCopyStatus" class="term-copy-status" role="status" aria-live="polite"></p><p>不同客戶與製程可能採用不同譯法，請依圖面上下文人工確認。來源：附件術語表；審核狀態：待企業確認。</p><div class="actions" style="justify-content:flex-end;margin-top:20px"><button onclick="this.closest('dialog').close()">關閉</button></div>`)}
function termCopyItems(t,language){return t[language].split(/\s*[/／]\s*/).filter(Boolean).map((word,index)=>`<span class="term-copy-item"><span>${esc(word)}</span><button type="button" class="term-copy-button" title="複製 ${esc(word)}" aria-label="複製 ${esc(word)}" onclick="copyTermWord(${t.id},'${language}',${index},this)"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg><span class="copy-label">複製</span></button></span>`).join('')}
async function copyTermWord(id,language,index,button){const t=glossaryTerms.find(t=>t.id===id);if(!t||!['zh','en','de'].includes(language))return;const word=t[language].split(/\s*[/／]\s*/).filter(Boolean)[index];if(!word)return;const status=document.querySelector('#termCopyStatus');let copied=false;try{await navigator.clipboard.writeText(word);copied=true}catch{const field=document.createElement('textarea');field.value=word;field.setAttribute('aria-label','待複製詞彙');field.style.cssText='position:fixed;opacity:0;left:0;top:0';(button.closest('dialog')||document.body).appendChild(field);field.select();try{copied=document.execCommand('copy')}catch{}field.remove();button.focus()}if(!copied){if(status)status.textContent='複製失敗，請選取詞彙後手動複製。';return}button.classList.add('copied');button.querySelector('.copy-label').textContent='已複製';button.setAttribute('aria-label','已複製 '+word);if(status)status.textContent='已複製：'+word;clearTimeout(button.copyResetTimer);button.copyResetTimer=setTimeout(()=>{if(!button.isConnected)return;button.classList.remove('copied');button.querySelector('.copy-label').textContent='複製';button.setAttribute('aria-label','複製 '+word)},2000)}
